import java.util.List;

public class Solution {
    public List<List<String>> solveNQueens(int n) {
        List<List<String>> result = new ArrayList<>();
        char[][] board = new char[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                board[i][j] = '.';
            }
        }
        solve(result, board, n, 0);
        return result;
    }

    private void solve(List<List<String>> result, char[][] board, int n, int col) {
        if (col == n) {
            List<String> solution = new ArrayList<>();
            for (char[] row : board) {
                solution.add(new String(row));
            }
            result.add(solution);
            return;
        }
        for (int row = 0; row < n; row++) {
            if (isSafe(board, row, col)) {
                board[row][col] = 'Q';
                solve(result, board, n, col + 1);
                board[row][col] = '.';
            }
        }
    }

    private boolean isSafe(char[][] board, int row, int col) {
        for (int i = 0; i < col; i++) {
            if (board[row][i] == 'Q') return false;
        }
        for (int i = row, j = col; i >= 0 && j >= 0; i--, j--) {
            if (board[i][j] == 'Q') return false;
        }
        for (int i = row, j = col; i < board.length && j >= 0; i++, j--) {
            if (board[i][j] == 'Q') return false;
        }
        return true;
    }
}

import java.util.ArrayList;
import java.util.List;

public class Solution {
    public int totalNQueens(int n) {
        List<Integer> cols = new ArrayList<>();
        return backtrack(n, cols);
    }

    private boolean isSafe(List<Integer> cols, int row) {
        int col = cols.size();
        for (int i = 0; i < col; i++) {
            if (cols.get(i) == row || Math.abs(i - col) == Math.abs(cols.get(i) - row)) {
                return false;
            }
        }
        return true;
    }

    private int backtrack(int n, List<Integer> cols) {
        if (cols.size() == n) {
            return 1;
        }

        int count = 0;
        for (int i = 0; i < n; i++) {
            if (isSafe(cols, i)) {
                cols.add(i);
                count += backtrack(n, cols);
                cols.remove(cols.size() - 1);
            }
        }

        return count;
    }
}

