    unordered_set<string> word_set(wordList.begin(), wordList.end());
    if (word_set.find(endWord) == word_set.end()) {
        return 0;
    }

    queue<string> q;
    q.push(beginWord);
    int steps = 1;

    while (!q.empty()) {
        int size = q.size();
        unordered_set<string> current_level;

        for (int i = 0; i < size; i++) {
            string current_word = q.front();
            q.pop();
            if (current_word == endWord) {
                return steps;
            }

            vector<char> word_chars(current_word.begin(), current_word.end());
            for (int j = 0; j < word_chars.size(); j++) {
                char original_char = word_chars[j];
                for (char c = 'a'; c <= 'z'; c++) {
                    word_chars[j] = c;
                    string new_word(word_chars.begin(), word_chars.end());
                    if (word_set.find(new_word) != word_set.end()) {
                        q.push(new_word);
                        current_level.insert(new_word);
                    }
                }
                word_chars[j] = original_char;
            }
        }

        word_set.erase(current_level.begin(), current_level.end());
        steps++;
    }

    return 0;
}

