string alienOrder(vector<string>& words) {
    unordered_map<char, unordered_set<char>> graph;
    unordered_map<char, int> in_degree;

    for (const string& word : words) {
        for (char c : word) {
            in_degree[c] = 0;
        }
    }

    for (int i = 0; i < words.size() - 1; ++i) {
        string word1 = words[i];
        string word2 = words[i + 1];
        int len = min(word1.length(), word2.length());
        bool found = false;
        for (int j = 0; j < len; ++j) {
            if (word1[j] != word2[j]) {
                if (graph[word1[j]].find(word2[j]) == graph[word1[j]].end()) {
                    graph[word1[j]].insert(word2[j]);
                    in_degree[word2[j]]++;
                }
                found = true;
                break;
            }
        }
        if (!found && word1.length() > word2.length()) {
            return "";
        }
    }

    queue<char> q;
    for (auto& pair : in_degree) {
        if (pair.second == 0) {
            q.push(pair.first);
        }
    }

    string result;
    while (!q.empty()) {
        char c = q.front();
        q.pop();
        result += c;

        for (char neigh : graph[c]) {
            in_degree[neigh]--;
            if (in_degree[neigh] == 0) {
                q.push(neigh);
            }
        }
    }

    if (result.length() < in_degree.size()) {
        return "";
    }

    return result;
}

