    std::vector<int> findMinHeightTrees(int n, std::vector<std::vector<int>>& edges) {
        if (n == 1) {
            return {0};
        }

        std::vector<std::unordered_set<int>> adj_list(n);
        for (const auto& edge : edges) {
            adj_list[edge[0]].insert(edge[1]);
            adj_list[edge[1]].insert(edge[0]);
