import java.util.Arrays;

public class Solution {
    public int countRangeSum(int[] nums, int lower, int upper) {
        int n = nums.length;
        long[] sums = new long[n + 1];
        for (int i = 0; i < n; i++) {
            sums[i + 1] = sums[i] + nums[i];
        }

        return mergeSort(sums, 0, n, lower, upper);
    }

    private int mergeSort(long[] sums, int start, int end, int lower, int upper) {
        if (start == end) {
            return 0;
        }
        int mid = start + (end - start) / 2;
        int count = mergeSort(sums, start, mid, lower, upper) + mergeSort(sums, mid + 1, end, lower, upper);

        int j = mid + 1, k = mid + 1;
        for (int i = start; i <= mid; i++) {
            while (j <= end && sums[j] - sums[i] < lower) {
                j++;
            }
            while (k <= end && sums[k] - sums[i] <= upper) {
                k++;
            }
            count += k - j;
        }

        long[] temp = new long[end - start + 1];
        int p = start, q = mid + 1, r = 0;
        while (p <= mid || q <= end) {
            if (q > end || (p <= mid && sums[p] < sums[q])) {
                temp[r++] = sums[p++];
            } else {
                temp[r++] = sums[q++];
            }
        }
        System.arraycopy(temp, 0, sums, start, temp.length);
        return count;
    }
}

