import java.util.Arrays;

public class Solution {
    private static final int[][] DIRECTIONS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

    public int longestIncreasingPath(int[][] matrix) {
        if (matrix == null || matrix.length == 0) {
            return 0;
        }

        int m = matrix.length;
        int n = matrix[0].length;
        int[][] memo = new int[m][n];
        int ans = 0;

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                ans = Math.max(ans, dfs(matrix, memo, i, j));
            }
        }

        return ans;
    }

    private int dfs(int[][] matrix, int[][] memo, int i, int j) {
        if (memo[i][j] != 0) {
            return memo[i][j];
        }

        int maxLen = 0;
        for (int[] direction : DIRECTIONS) {
            int ni = i + direction[0];
            int nj = j + direction[1];
            if (ni >= 0 && ni < matrix.length && nj >= 0 && nj < matrix[0].length && matrix[ni][nj] > matrix[i][j]) {
                maxLen = Math.max(maxLen, dfs(matrix, memo, ni, nj));
            }
        }

        memo[i][j] = maxLen + 1;
        return memo[i][j];
    }

    public static void main(String[] args) {
        Solution solution = new Solution();
        int[][] matrix = {{9, 9, 4}, {6, 6, 8}, {2, 1, 1}};
        System.out.println(solution.longestIncreasingPath(matrix)); // Output: 4
    }
}

