from collections import Counter

def leastInterval(tasks, n):
    task_freq = Counter(tasks)
    max_heap = [-freq for freq in task_freq.values()]
    heapq.heapify(max_heap)

    cycles = 0

    while max_heap:
        temp = []
        for _ in range(n + 1):
            if max_heap:
                temp.append(heapq.heappop(max_heap))

        for freq in temp:
