        int no_offer = helper(price, special, needs, index + 1);

        bool can_apply_offer = true;
        for (int i = 0; i < needs.size(); ++i) {
            needs[i] -= special[index][i];
            if (needs[i] < 0) {
                can_apply_offer = false;
            }
        }

        int with_offer = INT_MAX;
        if (can_apply_offer) {
            with_offer = special[index].back() + helper(price, special, needs, index);
        }

        for (int i = 0; i < needs.size(); ++i) {
            needs[i] += special[index][i];
        }

        return min(no_offer, with_offer);
