struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(NULL), right(NULL) {}
};

class Solution {
public:
    int count_nodes(TreeNode* node) {
        if (!node) return 0;
        return count_nodes(node->left) + count_nodes(node->right) + 1;
    }

    TreeNode* find_node(TreeNode* node, int x) {
        if (!node) return NULL;
        if (node->val == x) return node;
        TreeNode* left_search = find_node(node->left, x);
        if (left_search) return left_search;
        return find_node(node->right, x);
    }

    bool btree_game_winning_move(TreeNode* root, int n, int x) {
        TreeNode* x_node = find_node(root, x);
        int left_nodes = count_nodes(x_node->left);
        int right_nodes = count_nodes(x_node->right);
        int parent_nodes = n - left_nodes - right_nodes - 1;

        return max(max(left_nodes, right_nodes), parent_nodes) > n / 2;
