public class Solution {
    public String reformat(String s) {
        Deque<Character> letters = new ArrayDeque<>();
        Deque<Character> digits = new ArrayDeque<>();

        for (char c : s.toCharArray()) {
            if (Character.isLetter(c)) {
                letters.addLast(c);
            } else {
                digits.addLast(c);
            }
        }

        if (Math.abs(letters.size() - digits.size()) > 1) {
            return "";
        }

        StringBuilder result = new StringBuilder();
        boolean useLetter = letters.size() > digits.size();

        while (!letters.isEmpty() || !digits.isEmpty()) {
            if (useLetter) {
                result.append(letters.removeFirst());
            } else {
                result.append(digits.removeFirst());
            }
            useLetter = !useLetter;
        }

        return result.toString();
    }
}

