import java.util.List;

public class Solution {
    public double getProbability(int[] balls) {
        int sumBalls = 0;
        for (int ball : balls) {
            sumBalls += ball;
        }

        long totalCombinations = 1;
        for (int ball : balls) {
            totalCombinations *= factorial(ball);
        }

        List<Integer> combinations = new ArrayList<>();
        return dfs(balls, combinations, 0) / (double) totalCombinations;
    }

    private long dfs(int[] balls, List<Integer> combinations, int currBall) {
        if (currBall == balls.length) {
            if (combinations.get(combinations.size() - 1) == combinations.get(0)) {
                return countCombinations(balls, combinations, currBall);
            } else {
                return 0;
            }
        }

        long result = 0;
        for (int i = 0; i <= balls[currBall]; i++) {
            combinations.add(i);
            result += dfs(balls, combinations, currBall + 1);
            combinations.remove(combinations.size() - 1);
        }

        return result;
    }

    private long countCombinations(int[] balls, List<Integer> combinations, int currBall) {
        long totalCombinations = 1;
        for (int i = 0; i < currBall; i++) {
            totalCombinations *= factorial(balls[i] + combinations.get(i)) / (factorial(balls[i]) * factorial(combinations.get(i)));
        }

        return totalCombinations;
    }

    private long factorial(int n) {
        if (n == 0) {
            return 1;
        }
        return n * factorial(n - 1);
    }
}

