            return false;
        }

        Queue<TreeNode> q = new LinkedList<>();
        q.offer(root);
        int level = 0;

        while (!q.isEmpty()) {
            int size = q.size();
            int prevVal = level % 2 == 0 ? 0 : Integer.MAX_VALUE;

            for (int i = 0; i < size; i++) {
                TreeNode curr = q.poll();

                if ((level % 2 == 0 && (curr.val % 2 == 0 || curr.val <= prevVal)) || 
                    (level % 2 != 0 && (curr.val % 2 != 0 || curr.val >= prevVal))) {
                    return false;
                }

                prevVal = curr.val;

                if (curr.left != null) {
                    q.offer(curr.left);
                }
                if (curr.right != null) {
                    q.offer(curr.right);
                }
            }

            level++;
        }

        return true;
    }
}

