    for (int i = 1; i < n - 1; i += 2) {
        non_first_xor ^= encoded[i];
    }

    std::vector<int> perm = {total_xor ^ non_first_xor};
    for (int i = 1; i < n; ++i) {
        perm.push_back(perm.back() ^ encoded[i - 1]);
    }

    return perm;
}

